using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class MartOpenBillboard{const string D="Assets/Scenes/Oasis/SuperMart3DSigns/";static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;static MartOpenBillboard(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MartOpenBillboard.request"))return;File.Delete("MartOpenBillboard.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MartOpenBillboard.txt",e.ToString());Debug.LogException(e);}}struct V{public Vector3 p;public Vector2[] uv;}static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(scene.GetRootGameObjects().Any(g=>g.name=="Super Mart Open Neon Roadside Logo"))throw new Exception("Open billboard already installed");var f=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Single(g=>g.name=="billboard (47)");var original=f.sharedMesh;var originalMatrix=f.transform.localToWorldMatrix;var data=typeof(FinalPNGCityDetails).GetMethod("Read",F).Invoke(null,new object[]{original});var p=(Vector3[])data.GetType().GetField("p").GetValue(data);var uv=(Vector2[][])data.GetType().GetField("uv").GetValue(data);var ids=(int[])data.GetType().GetField("ids").GetValue(data);var world=p.Select(f.transform.TransformPoint).ToArray();float cutoff=999,best=-999;var normal=Vector3.left;for(int k=0;k<ids.Length;k+=3){var a=world[ids[k]];var b=world[ids[k+1]];var c=world[ids[k+2]];var n=Vector3.Cross(b-a,c-a);if(n.magnitude>4&&Mathf.Abs(n.normalized.y)<.2f&&(a.y+b.y+c.y)/3>34){cutoff=Mathf.Min(cutoff,Mathf.Min(a.y,Mathf.Min(b.y,c.y)));float score=Vector3.Dot(n.normalized,Vector3.left);if(score>best){best=score;normal=n.normalized;}}}if(cutoff<33||cutoff>37)throw new Exception("Billboard head separation failed "+cutoff);cutoff-=.025f;Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeMartOpenBillboard");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeMartOpenBillboard/Scene.unity",true);var pp=new List<Vector3>();var uu=new List<Vector2>[8];for(int c=0;c<8;c++)uu[c]=new List<Vector2>();var ii=new List<int>();Func<int,V> vertex=i=>new V{p=p[i],uv=Enumerable.Range(0,8).Select(c=>uv[c]!=null?uv[c][i]:Vector2.zero).ToArray()};Func<V,V,float,V> mix=(a,b,t)=>new V{p=Vector3.Lerp(a.p,b.p,t),uv=Enumerable.Range(0,8).Select(c=>Vector2.Lerp(a.uv[c],b.uv[c],t)).ToArray()};for(int k=0;k<ids.Length;k+=3){var poly=new[]{vertex(ids[k]),vertex(ids[k+1]),vertex(ids[k+2])};var clipped=new List<V>();for(int j=0;j<3;j++){var a=poly[j];var b=poly[(j+1)%3];float ay=f.transform.TransformPoint(a.p).y,by=f.transform.TransformPoint(b.p).y;bool ain=ay<=cutoff,bin=by<=cutoff;if(ain)clipped.Add(a);if(ain!=bin)clipped.Add(mix(a,b,(cutoff-ay)/(by-ay)));}for(int j=1;j<clipped.Count-1;j++){int count=pp.Count;foreach(var v in new[]{clipped[0],clipped[j],clipped[j+1]}){pp.Add(v.p);for(int c=0;c<8;c++)uu[c].Add(v.uv[c]);}ii.AddRange(new[]{count,count+1,count+2});}}var lower=new Mesh{name="Original supermarket roadside billboard pole platform only"};lower.SetVertices(pp);for(int c=0;c<8;c++)if(uv[c]!=null)lower.SetUVs(c,uu[c]);lower.SetTriangles(ii,0);lower.RecalculateNormals();lower.RecalculateTangents();lower.RecalculateBounds();AssetDatabase.CreateAsset(lower,D+"Existing roadside billboard retained pole platform.asset");f.sharedMesh=lower;var collider=f.GetComponent<MeshCollider>();if(collider)collider.sharedMesh=lower;PrefabUtility.RecordPrefabInstancePropertyModifications(f);var near=StackHouse3DSigns.BuildSuperMartSign(3,true);var far=StackHouse3DSigns.BuildSuperMartSign(3,false);AssetDatabase.CreateAsset(near,D+"Super Mart open neon roadside near.asset");AssetDatabase.CreateAsset(far,D+"Super Mart open neon roadside far.asset");var root=new GameObject("Super Mart Open Neon Roadside Logo");root.transform.SetPositionAndRotation(new Vector3(f.transform.position.x,cutoff+1.04f,f.transform.position.z),Quaternion.LookRotation(normal));root.transform.localScale=Vector3.one*.5f;var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Cafe.mat");var renderers=new Renderer[2];for(int k=0;k<2;k++){var child=new GameObject(k==0?"Open raised SUPER MART and shopping cart near":"Open logo far");child.transform.SetParent(root.transform,false);child.AddComponent<MeshFilter>().sharedMesh=k==0?near:far;renderers[k]=child.AddComponent<MeshRenderer>();renderers[k].sharedMaterial=mat;}var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.045f,new[]{renderers[0]}),new LOD(.003f,new[]{renderers[1]})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAssetAndConnect(root,D+"Super Mart Open Neon Roadside Logo.prefab",InteractionMode.AutomatedAction);if(f.transform.localToWorldMatrix!=originalMatrix)throw new Exception("Pole transform changed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",F);var center=root.transform.position;capture.Invoke(null,new object[]{scene,center+normal*17+Vector3.up*2,center+Vector3.down*1.3f,"SuperMart-Open-Neon-Billboard"});File.WriteAllText("FinalEnvironmentRoadReview/MartOpenBillboard.txt","SUCCESS billboard (47) rectangular advert head removed at y="+cutoff+"; native pole/platform geometry retained by clipping, original transform preserved. Open 3D SUPER MART lettering/cart with luminous trim, no rectangular sign backing, near/far LOD. Same existing Cafe atlas/material. No new texture/material. Facing="+normal+" shader errors="+ShaderUtil.ShaderHasError(mat.shader));}}
